static bool read_file(const char *path, uint8_t **out_bytes, size_t *out_length)
{
    *out_bytes = NULL;
    *out_length = 0U;
    FILE *file = fopen(path, "rb");
    if (file == NULL) return false;
    bool ok = fseek(file, 0, SEEK_END) == 0;
    long length = ok ? ftell(file) : -1L;
    if (length < 0L || length > 16L * 1024L * 1024L) ok = false;
    if (ok && fseek(file, 0, SEEK_SET) != 0) ok = false;
    size_t size = ok ? (size_t)length : 0U;
    uint8_t *bytes = ok ? malloc(size == 0U ? 1U : size) : NULL;
    if (ok && bytes == NULL) ok = false;
    if (ok && fread(bytes, 1U, size, file) != size) ok = false;
    if (fclose(file) != 0) ok = false;
    if (!ok) { free(bytes); return false; }
    *out_bytes = bytes;
    *out_length = size;
    return true;
}

static void make_translucent(svg_shape_document *doc)
{
    for (size_t edge = 0U; edge < doc->edge_count; edge++) {
        if (doc->colors[edge * 4U + 3U] != 0U)
            doc->colors[edge * 4U + 3U] =
                (uint8_t)(48U + ((size_t)doc->shape_ids[edge] * 73U) % 192U);
    }
    for (size_t shape = 0U; shape < doc->shape_count; shape++) {
        if (doc->strokes[shape].rgba[3] != 0U)
            doc->strokes[shape].rgba[3] = (uint8_t)(64U + (shape * 47U) % 160U);
    }
}

int main(int argc, char **argv)
{
    bool translucent = argc == 4 && strcmp(argv[1], "--translucent") == 0;
    if (argc != (translucent ? 4 : 3)) return 2;
    const char *input_path = argv[translucent ? 2 : 1];
    const char *output_path = argv[translucent ? 3 : 2];
    uint8_t *bytes = NULL;
    size_t length = 0U;
    if (!read_file(input_path, &bytes, &length)) return 2;
    svg_shape_document doc = {0};
    svg_shape_diagnostic diag = {0};
    if (svg_shape_decode((base_bytes){bytes, length}, &doc, &diag) != SVG_SHAPE_ERROR_NONE) {
        fprintf(stderr, "%s:%zu\n", svg_shape_error_name(diag.category), diag.offset);
        free(bytes);
        return 1;
    }
    if (translucent) make_translucent(&doc);
    raster_tile tile = {0};
    raster_shape_work_stats work = {0};
    bool rendered = translucent ?
        raster_shape_render_with_stats_scalar_oracle_alpha(&doc, &tile,
                                                           &diag, &work) :
        raster_shape_render_with_stats(&doc, &tile, &diag, &work);
    if (!rendered) {
        fprintf(stderr, "%s:%zu\n", svg_shape_error_name(diag.category), diag.offset);
        svg_shape_document_destroy(&doc);
        free(bytes);
        return 1;
    }
    raster_tile reference_tile = {0};
    if (translucent &&
        (!raster_shape_render_reference(&doc, &reference_tile, &diag) ||
         reference_tile.byte_count != tile.byte_count ||
         memcmp(reference_tile.rgba, tile.rgba, tile.byte_count) != 0)) {
        size_t mismatch = 0U;
        while (mismatch < tile.byte_count && reference_tile.rgba != NULL &&
               tile.rgba[mismatch] == reference_tile.rgba[mismatch]) mismatch++;
        fprintf(stderr, "reference-mismatch:%zu\n", mismatch);
        raster_tile_destroy(&reference_tile);
        raster_tile_destroy(&tile);
        svg_shape_document_destroy(&doc);
        free(bytes);
        return 3;
    }
    FILE *output = fopen(output_path, "wb");
    bool ok = output != NULL && fwrite(tile.rgba, 1U, tile.byte_count, output) == tile.byte_count;
    if (output != NULL && fclose(output) != 0) ok = false;
    if (ok) {
        fprintf(stderr, "shape_pixels=%" PRIu64 "\n", work.shape_pixels);
        fprintf(stderr, "shape_samples=%" PRIu64 "\n", work.shape_samples);
        fprintf(stderr, "fill_edge_tests=%" PRIu64 "\n", work.fill_edge_tests);
        fprintf(stderr, "fill_interval_tests=%" PRIu64 "\n",
                work.fill_interval_tests);
        fprintf(stderr, "stroke_tests=%" PRIu64 "\n", work.stroke_tests);
        fprintf(stderr, "scanline_edge_entries=%" PRIu64 "\n", work.scanline_edge_entries);
        fprintf(stderr, "shape_row_visits=%" PRIu64 "\n", work.shape_row_visits);
        fprintf(stderr, "boundary_mark_work=%" PRIu64 "\n", work.boundary_mark_work);
        fprintf(stderr, "total_work=%" PRIu64 "\n", work.total_work);
    }
    raster_tile_destroy(&reference_tile);
    raster_tile_destroy(&tile);
    svg_shape_document_destroy(&doc);
    free(bytes);
    return ok ? 0 : 2;
}

/* WO-CORPUS-01: unknown non-namespaced attributes, <meta>, <!DOCTYPE> and
 * writing-mode are ignored for rendering and reported, never fatal. */
#include "shape.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int failures;

static void check(bool condition, const char *what)
{
    if (!condition) {
        fprintf(stderr, "FAIL: %s\n", what);
        failures++;
    } else {
        printf("ok: %s\n", what);
    }
}

static svg_shape_error decode(const char *text, svg_shape_document *doc)
{
    svg_shape_diagnostic diagnostic = {0};
    return svg_shape_decode((base_bytes){(const uint8_t *)text, strlen(text)}, doc, &diagnostic);
}

static bool same_render(const svg_shape_document *a, const svg_shape_document *b)
{
    return a->shape_count == b->shape_count && a->edge_count == b->edge_count &&
           a->edge_count != 0U &&
           memcmp(a->edges, b->edges, a->edge_count * sizeof(*a->edges)) == 0 &&
           memcmp(a->colors, b->colors, a->edge_count * 4U) == 0;
}

static size_t offset_of(const char *text, const char *needle)
{
    const char *at = strstr(text, needle);
    return at == NULL ? SIZE_MAX : (size_t)(at - text);
}

/* Decodes `with` and `without`: both succeed, render identically, and `with`
 * reports exactly `count` ignored entries of `kind`, the first at `needle`. */
static void expect_ignored(const char *name, const char *with, const char *without,
                           svg_shape_ignored_kind kind, size_t count, const char *needle)
{
    svg_shape_document a = {0}, b = {0};
    svg_shape_error ea = decode(with, &a), eb = decode(without, &b);
    check(ea == SVG_SHAPE_ERROR_NONE && eb == SVG_SHAPE_ERROR_NONE, name);
    if (ea != SVG_SHAPE_ERROR_NONE || eb != SVG_SHAPE_ERROR_NONE) goto done;
    check(same_render(&a, &b), "  renders as without the construct");
    check(a.ignored[kind].count == count, "  summary count");
    check(a.ignored[kind].first_offset == offset_of(with, needle), "  summary first offset");
    for (unsigned k = 0U; k < SVG_SHAPE_IGNORED_KIND_COUNT; ++k)
        if (k != (unsigned)kind) check(a.ignored[k].count == 0U, "  no other kind reported");
    check(b.ignored[kind].count == 0U, "  clean document reports nothing");
done:
    svg_shape_document_destroy(&a);
    svg_shape_document_destroy(&b);
}

#define RECT "<rect x=\"1\" y=\"1\" width=\"4\" height=\"3\" fill=\"red\""

int main(void)
{
    expect_ignored("unknown attributes",
        "<svg width=\"8\" height=\"8\" data-doc=\"1\">" RECT " data-a=\"1\" foo=\"bar\"/></svg>",
        "<svg width=\"8\" height=\"8\">" RECT "/></svg>",
        SVG_SHAPE_IGNORED_UNKNOWN_ATTRIBUTE, 3U, "data-doc");
    expect_ignored("unknown attribute on a group",
        "<svg width=\"8\" height=\"8\"><g custom=\"x\">" RECT "/></g></svg>",
        "<svg width=\"8\" height=\"8\"><g>" RECT "/></g></svg>",
        SVG_SHAPE_IGNORED_UNKNOWN_ATTRIBUTE, 1U, "custom");
    expect_ignored("meta element",
        "<svg width=\"8\" height=\"8\"><meta charset=\"utf-8\"/>" RECT "/></svg>",
        "<svg width=\"8\" height=\"8\">" RECT "/></svg>",
        SVG_SHAPE_IGNORED_META, 1U, "<meta");
    expect_ignored("doctype with public identifier",
        "<?xml version=\"1.0\"?>\n<!DOCTYPE svg PUBLIC \"-//W3C//DTD SVG 1.1//EN\" \"x.dtd\">\n"
        "<svg width=\"8\" height=\"8\">" RECT "/></svg>",
        "<svg width=\"8\" height=\"8\">" RECT "/></svg>",
        SVG_SHAPE_IGNORED_DOCTYPE, 1U, "<!DOCTYPE");
    expect_ignored("doctype with internal subset",
        "<!DOCTYPE svg [<!-- ]> --><!ENTITY e \"x>y]\"><?p ]>?>]>"
        "<svg width=\"8\" height=\"8\">" RECT "/></svg>",
        "<svg width=\"8\" height=\"8\">" RECT "/></svg>",
        SVG_SHAPE_IGNORED_DOCTYPE, 1U, "<!DOCTYPE");
    expect_ignored("writing-mode attribute, style attribute and stylesheet",
        "<svg width=\"8\" height=\"8\"><style>.a{writing-mode:tb}</style>"
        RECT " writing-mode=\"tb\"/><g style=\"fill:red; writing-mode : tb-rl\"/></svg>",
        "<svg width=\"8\" height=\"8\"><style>.a{}</style>" RECT "/><g/></svg>",
        SVG_SHAPE_IGNORED_WRITING_MODE, 3U, "writing-mode:tb");

    {
        svg_shape_document doc = {0};
        svg_shape_error e = decode(
            "<svg width=\"8\" height=\"8\" xmlns:x=\"urn:x\">" RECT " x:foo=\"1\"/></svg>", &doc);
        check(e == SVG_SHAPE_ERROR_NONE && doc.ignored[0].count == 0U,
              "namespaced foreign attribute stays silently ignored");
        svg_shape_document_destroy(&doc);
    }
    {
        svg_shape_document doc = {0};
        svg_shape_error e = decode(
            "<svg width=\"8\" height=\"8\">" RECT " text-decoration=\"underline\"/></svg>", &doc);
        check(e == SVG_SHAPE_ERROR_UNSUPPORTED,
              "a known rendering attribute that is unsupported still fails closed");
    }
    {
        svg_shape_document doc = {0};
        check(decode("<!DOCTYPE svg [<!ENTITY e \"x\">]><svg width=\"8\" height=\"8\">"
                     "<text>&e;</text></svg>", &doc) == SVG_SHAPE_ERROR_XML,
              "DOCTYPE entity referenced in text still fails as XML, unexpanded");
        check(decode("<!DOCTYPE svg [<!ENTITY e \"1\">]><svg width=\"8\" height=\"8\">"
                     RECT " x=\"&e;\"/></svg>", &doc) == SVG_SHAPE_ERROR_XML,
              "DOCTYPE entity referenced in an attribute still fails as XML");
        check(decode("<svg width=\"8\" height=\"8\"/><!DOCTYPE svg>", &doc) == SVG_SHAPE_ERROR_XML,
              "DOCTYPE after the root element is still an XML error");
    }
    if (failures != 0) {
        fprintf(stderr, "%d failure(s)\n", failures);
        return 1;
    }
    puts("ignored-construct tests passed");
    return 0;
}

#include "test_m4_06_evidence.h"
#include "shape.h"
#include "shape_render.h"

#include <CommonCrypto/CommonDigest.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define USE_BIG_BYTES (64U * 1024U - 1U)
#define JOB_LIMIT_BYTES (1024U * 1024U)

/* Appends a defs target "<g id=ID><!--a...a--></g>" of exactly total bytes. */
static char *append_target(char *cursor, const char *id, size_t total)
{
    int head = snprintf(cursor, 64U, "<g id=\"%s\"><!--", id);
    if (head < 0 || total < (size_t)head + 3U + 4U) return NULL;
    size_t payload = total - (size_t)head - 3U - 4U;
    memset(cursor + head, 'a', payload);
    cursor += (size_t)head + payload;
    memcpy(cursor, "--></g>", 7U);
    return cursor + 7U;
}

/* 16 uses of a 65,535-byte target plus one use of a tiny target of tiny_bytes. */
static bool decode_job_total(size_t tiny_bytes, const char *tiny_id,
                             svg_shape_error expected)
{
    static const char prefix[] = "<svg width=\"1\" height=\"1\"><defs>";
    static const char suffix[] = "</defs>";
    size_t capacity = sizeof(prefix) + USE_BIG_BYTES + tiny_bytes +
                      sizeof(suffix) + 17U * 24U + 16U;
    char *source = malloc(capacity);
    if (source == NULL) return false;
    char *cursor = source;
    memcpy(cursor, prefix, sizeof(prefix) - 1U);
    cursor += sizeof(prefix) - 1U;
    char *start = cursor;
    cursor = append_target(cursor, "big", USE_BIG_BYTES);
    if (cursor == NULL || (size_t)(cursor - start) != USE_BIG_BYTES) { free(source); return false; }
    start = cursor;
    cursor += (size_t)snprintf(cursor, 64U, "<g id=\"%s\"/>", tiny_id);
    if ((size_t)(cursor - start) != tiny_bytes) { free(source); return false; }
    memcpy(cursor, suffix, sizeof(suffix) - 1U);
    cursor += sizeof(suffix) - 1U;
    for (unsigned i = 0U; i < 16U; ++i) {
        memcpy(cursor, "<use href=\"#big\"/>", 18U);
        cursor += 18U;
    }
    cursor += (size_t)snprintf(cursor, 64U, "<use href=\"#%s\"/></svg>", tiny_id);
    size_t length = (size_t)(cursor - source);
    unsigned char before[CC_SHA256_DIGEST_LENGTH], after[CC_SHA256_DIGEST_LENGTH];
    svg_shape_document document = {0};
    svg_shape_diagnostic diagnostic = {0};
    bool ok = CC_SHA256(source, (CC_LONG)length, before) != NULL &&
              16U * USE_BIG_BYTES + tiny_bytes ==
                  JOB_LIMIT_BYTES + (expected == SVG_SHAPE_ERROR_NONE ? 0U : 1U);
    svg_shape_error error = ok ? svg_shape_decode(
        (base_bytes){(const uint8_t *)source, length}, &document, &diagnostic)
        : SVG_SHAPE_ERROR_XML;
    ok = ok && error == expected &&
         (expected != SVG_SHAPE_ERROR_LIMIT || diagnostic.category == SVG_SHAPE_ERROR_LIMIT) &&
         CC_SHA256(source, (CC_LONG)length, after) != NULL &&
         memcmp(before, after, sizeof(before)) == 0;
    if (!ok) fprintf(stderr, "job reference total tiny=%zu: expected %d got %d\n",
                     tiny_bytes, (int)expected, (int)error);
    svg_shape_document_destroy(&document);
    free(source);
    return ok;
}

/* Long %.17g viewBox values must fit the generated userSpaceOnUse wrapper. */
static bool clip_wrapper_extreme_check(void)
{
    static const char source[] =
        "<svg width=\"4096\" height=\"4096\" "
        "viewBox=\"-1234.1234567891 -1234.1234567891 "
        "4096.1234567891 4096.1234567891\">"
        "<defs><clipPath id=\"c\" clipPathUnits=\"userSpaceOnUse\"><rect width=\"1\" height=\"1\"/></clipPath></defs>"
        "<rect width=\"1\" height=\"1\" clip-path=\"url(#c)\"/></svg>";
    unsigned char before[CC_SHA256_DIGEST_LENGTH], after[CC_SHA256_DIGEST_LENGTH];
    svg_shape_document document = {0};
    svg_shape_diagnostic diagnostic = {0};
    if (CC_SHA256(source, (CC_LONG)(sizeof(source) - 1U), before) == NULL) return false;
    svg_shape_error error = svg_shape_decode(
        (base_bytes){(const uint8_t *)source, sizeof(source) - 1U}, &document, &diagnostic);
    bool ok = error == SVG_SHAPE_ERROR_NONE &&
              CC_SHA256(source, (CC_LONG)(sizeof(source) - 1U), after) != NULL &&
              memcmp(before, after, sizeof(before)) == 0;
    if (!ok) fprintf(stderr, "clip wrapper extreme: error %d\n", (int)error);
    svg_shape_document_destroy(&document);
    return ok;
}

static bool render_rgba(const char *source, raster_tile *tile, svg_shape_document *doc)
{
    svg_shape_diagnostic diagnostic = {0};
    if (svg_shape_decode((base_bytes){(const uint8_t *)source, strlen(source)}, doc,
                         &diagnostic) != SVG_SHAPE_ERROR_NONE) return false;
    if (!raster_shape_render(doc, tile, &diagnostic)) {
        svg_shape_document_destroy(doc);
        return false;
    }
    return true;
}

static bool pixel_is(const raster_tile *tile, uint32_t x, uint32_t y,
                     unsigned r, unsigned g, unsigned b, unsigned a)
{
    const uint8_t *p = tile->rgba + ((size_t)y * tile->width + x) * 4U;
    bool ok = p[0] == r && p[1] == g && p[2] == b && p[3] == a;
    if (!ok) fprintf(stderr, "pixel (%u,%u): expected %u,%u,%u,%u got %u,%u,%u,%u\n",
                     x, y, r, g, b, a, p[0], p[1], p[2], p[3]);
    return ok;
}

/* Pixel-center t=(x+0.5)/16, channel = round(255*(1-t)) / round(255*t). */
static bool exact_gradient_check(void)
{
    static const char linear[] =
        "<svg width=\"16\" height=\"16\"><defs><linearGradient id=\"g\">"
        "<stop offset=\"0\" stop-color=\"#ff0000\"/>"
        "<stop offset=\"1\" stop-color=\"#0000ff\"/></linearGradient></defs>"
        "<rect width=\"16\" height=\"16\" fill=\"url(#g)\"/></svg>";
    raster_tile tile = {0};
    svg_shape_document doc = {0};
    if (!render_rgba(linear, &tile, &doc)) return false;
    /* x=0: t=1/32 -> 247.03/7.97; x=8: t=17/32 -> 119.53/135.47; x=15: t=31/32. */
    bool ok = pixel_is(&tile, 0U, 8U, 247U, 0U, 8U, 255U) &&
              pixel_is(&tile, 8U, 8U, 120U, 0U, 135U, 255U) &&
              pixel_is(&tile, 15U, 8U, 8U, 0U, 247U, 255U);
    raster_tile_destroy(&tile);
    svg_shape_document_destroy(&doc);
    if (!ok) return false;
    /* Blue stop-opacity 0 -> 1 over opaque red; x=8: a=17/32 -> R 119.53, B 135.47. */
    static const char alpha[] =
        "<svg width=\"16\" height=\"16\"><defs><linearGradient id=\"g\">"
        "<stop offset=\"0\" stop-color=\"#0000ff\" stop-opacity=\"0\"/>"
        "<stop offset=\"1\" stop-color=\"#0000ff\" stop-opacity=\"1\"/></linearGradient></defs>"
        "<rect width=\"16\" height=\"16\" fill=\"#ff0000\"/>"
        "<rect width=\"16\" height=\"16\" fill=\"url(#g)\"/></svg>";
    if (!render_rgba(alpha, &tile, &doc)) return false;
    ok = pixel_is(&tile, 8U, 8U, 120U, 0U, 135U, 255U);
    raster_tile_destroy(&tile);
    svg_shape_document_destroy(&doc);
    return ok;
}

